-- Suppliers are proposed within 50 km of the site (Henrique's rule): a request from
-- Liège or Namur must not get offers from Brussels. Distances run between the centres
-- of the postal codes (average of the localities of each code, data: jief/zipcode-belgium).

create table public.postal_points (
  postal_code text primary key check (postal_code ~ '^[1-9][0-9]{3}$'),
  lat double precision not null,
  lng double precision not null
);
alter table public.postal_points enable row level security;
create policy "postal points are public" on public.postal_points for select to anon, authenticated using (true);
revoke insert, update, delete on public.postal_points from anon, authenticated;


/** Kilometres between the centres of two postal codes; null when one is unknown. */
create function public.postal_km(a text, b text) returns double precision
language sql stable set search_path = public as $$
  select 2 * 6371 * asin(sqrt(
    power(sin(radians(q.lat - p.lat) / 2), 2) +
    cos(radians(p.lat)) * cos(radians(q.lat)) * power(sin(radians(q.lng - p.lng) / 2), 2)))
  from public.postal_points p, public.postal_points q
  where p.postal_code = a and q.postal_code = b
$$;

/** Suppliers of a category (any when null) within 50 km of a postal code, nearest first.
    A supplier whose own postal code is unknown falls back to the areas it declared. */
create function public.nearby_suppliers(p_postal text, p_category smallint)
returns table (id uuid, km double precision)
language sql stable security definer set search_path = public as $$
  select c.id, min(public.postal_km(c.postal_code, p_postal)) as km
  from public.companies c
  join public.supplier_coverage sc on sc.supplier_id = c.id and (p_category is null or sc.category_id = p_category)
  where c.kind = 'supplier' and c.requests_stopped_at is null and c.deleted_at is null
    and (
      public.postal_km(c.postal_code, p_postal) <= 50
      or (public.postal_km(c.postal_code, p_postal) is null and p_postal like sc.postal_prefix || '%')
    )
  group by c.id
  order by km nulls last
$$;
revoke execute on function public.nearby_suppliers(text, smallint) from public, anon, authenticated;
grant execute on function public.nearby_suppliers(text, smallint) to service_role;

create or replace function public.match_suppliers(p_request_id uuid)
returns table (id uuid, name text, city text, verified boolean)
language sql stable security definer set search_path = public as $$
  with r as (
    select * from public.price_requests where id = p_request_id and company_id = public.my_company_id()
  ), near as (
    select n.id, n.km from r, public.nearby_suppliers(r.postal_code, r.category_id) n
  ), fav as (
    select ps.supplier_id as id from r join public.preferred_suppliers ps on ps.contractor_id = r.company_id
  )
  select c.id, c.name, c.city, c.verified_at is not null
  from public.companies c
  left join near on near.id = c.id
  left join fav on fav.id = c.id
  where c.kind = 'supplier' and c.requests_stopped_at is null and (near.id is not null or fav.id is not null)
  order by (fav.id is not null) desc, near.km nulls last, c.name
$$;

create or replace function public.supplier_reach(p_postal text) returns json
language sql stable security definer set search_path = public as $$
  with near as (
    select distinct n.id as supplier_id, sc.category_id
    from public.nearby_suppliers(p_postal, null) n
    join public.supplier_coverage sc on sc.supplier_id = n.id
    where p_postal ~ '^[1-9][0-9]{3}$'
  )
  select json_build_object(
    'total', (select count(distinct supplier_id) from near),
    'categories', coalesce((
      select json_agg(json_build_object('fr', k.label_fr, 'nl', k.label_nl, 'count', n.count) order by n.count desc)
      from (select category_id, count(*) from near group by category_id) n
      join public.categories k on k.id = n.category_id
    ), '[]'::json)
  )
$$;
